function careGuardian(){return shell(`<div class="care-space">${v3Banner(T('GUARDIAN CARE HUB','অভিভাবকের যত্ন'),T('Support begins with listening.','মন দিয়ে শোনা থেকেই যত্ন শুরু।'),T('A gentle place for parents and guardians of primary-school children.','প্রাথমিক বিদ্যালয়ের শিশুদের অভিভাবকদের জন্য।'))}<section class="care-guardian-hero"><div><span class="care-overline dark">${T('FAMILY-CENTRED GUIDANCE','পরিবারকে কেন্দ্র করে')}</span><h2>${T('Notice what you can see. Make space for what your child feels.','যা দেখছেন তা লক্ষ্য করুন, শিশুর কথা শোনার সময় দিন।')}</h2><p>${T('Caregivers can observe changes in sleep, play, school participation and social interactions. A child may experience feelings that adults cannot directly see.','ঘুম, খেলা, স্কুল ও সামাজিক আচরণের পরিবর্তন লক্ষ্য করুন। শিশুর কিছু অনুভূতি বড়রা সরাসরি বুঝতে নাও পারেন।')}</p><div class="care-actions"><a href="#/home" class="v3-main-button">${T('Choose primary school','প্রাথমিক স্তর বেছে নিন')} ↗</a><a href="#/support" class="care-quiet-button">${T('Professional support','বিশেষজ্ঞ সহায়তা')} ↗</a></div></div><img src="./parent-child-reflection.webp" alt="Parent listening to a child while drawing" loading="lazy"></section>
 <div class="care-title-row"><div><span class="care-overline dark">${T('OBSERVE · LISTEN · CONNECT','দেখুন · শুনুন · সাহায্য নিন')}</span><h2>${T('A thoughtful approach to family wellbeing.','পরিবারের যত্নের সহজ উপায়।')}</h2></div></div><div class="care-three-grid"><article><span>01</span><h3>${T('Observe patterns','আচরণের ধরন দেখুন')}</h3><p>${T('Notice changes in daily routines rather than trying to label an emotion. Consider when changes occur and what may be happening around the child.','অনুভূতির নাম না দিয়ে রোজকার আচরণের পরিবর্তন লক্ষ্য করুন। কখন হচ্ছে, আশপাশে কী ঘটছে ভাবুন।')}</p></article><article><span>02</span><h3>${T('Invite conversation','কথা বলার সুযোগ দিন')}</h3><p>${T('Try gentle, open questions during play or a familiar routine. Avoid blaming, pressuring or forcing an answer.','খেলা বা পরিচিত রুটিনে সহজ প্রশ্ন করুন। দোষ দেওয়া বা উত্তর দেওয়ার চাপ এড়ান।')}</p></article><article><span>03</span><h3>${T('Work together','একসঙ্গে সাহায্য করুন')}</h3><p>${T('If changes persist, coordinate with a teacher and a qualified child health professional. Support is not a punishment.','পরিবর্তন চললে শিক্ষক ও শিশু-স্বাস্থ্য বিশেষজ্ঞের সঙ্গে আলোচনা করুন। সাহায্য শাস্তি নয়।')}</p></article></div>
 <div class="care-guardian-bottom"><article class="care-paper"><h3>${T('Conversation starters','আলাপ শুরুর কথা')}</h3><ul><li>${T('What was one interesting part of school today?','আজ স্কুলে কোন বিষয়টি ভালো লেগেছে?')}</li><li>${T('Was there a moment you wished someone helped?','কোনো সময় সাহায্যের দরকার হয়েছিল?')}</li><li>${T('Would you like to tell me, draw it, or talk later?','বলবে, আঁকবে, নাকি পরে কথা বলবে?')}</li></ul></article><article class="care-paper"><h3>${T('Parent / guardian resources','অভিভাবকদের জন্য')}</h3><p>${T('Explore child wellbeing education from UNICEF, and the guardian-focused selection of Watch & Learn videos.','ইউনিসেফের শিশু-স্বাস্থ্য তথ্য এবং অভিভাবকদের জন্য ভিডিও দেখুন।')}</p><div class="care-stack"><a href="https://www.unicef.org/parenting/mental-health" target="_blank" rel="noopener noreferrer">UNICEF Parenting ↗</a><a href="#/videos">${T('Watch & Learn','ভিডিও দেখুন')} ↗</a><a href="#/literacy">${T('Literacy Centre','শিক্ষাকেন্দ্র')} ↗</a></div></article></div></div>`,true);}
function careAcademic(){const factors=careFactors[state.level]||careFactors.ug,guardian=state.level==='primary';const result=careResults;
 return shell(`<div class="care-space">${v3Banner(T('ACADEMIC PRESSURE REFLECTION','শিক্ষাগত চাপ পর্যবেক্ষণ'),T(guardian?'What changes have you observed?':'What feels demanding right now?',guardian?'কোন পরিবর্তনগুলি দেখেছেন?':'এখন কোনটি চাপ তৈরি করছে?'),T(guardian?'For parents and guardians: reflect only on things you have observed in your child over the past two weeks.':'Choose how often each area has felt difficult during the past two weeks. This is a reflection, not a diagnosis.',guardian?'অভিভাবকেরা গত দুই সপ্তাহে শিশুর যেসব আচরণ দেখেছেন তাই বলুন।':'গত দুই সপ্তাহে প্রতিটি বিষয় কতবার কঠিন লেগেছে বেছে নিন। এটি রোগনির্ণয় নয়।'))}
 <div class="care-academic-layout"><section class="care-paper"><div class="care-row"><strong>${T('Your learning stage','শিক্ষাস্তর')}: ${esc(state.level?nameOf(state.level):T('Not selected','নির্বাচিত নয়'))}</strong><a class="care-text-link" href="#/home">${T('Change stage','স্তর বদলান')} ↗</a></div>${!state.profileReady?`<div class="care-empty"><span>✦</span><h3>${T('Choose your learning stage first.','আগে শিক্ষাস্তর বেছে নিন।')}</h3><p>${T('This ensures questions reflect your educational context. Primary-school answers must be given by a parent or guardian.','প্রশ্নগুলি শিক্ষাস্তর অনুযায়ী হবে। প্রাথমিকের উত্তর দেবেন অভিভাবক।')}</p><a href="#/home" class="v3-main-button">${T('Choose my stage','স্তর বেছে নিন')} ↗</a></div>`:`<form id="care-academic-form"><p class="care-form-intro">${T(guardian?'How often have you observed the following?':'How often have you experienced difficulties in these areas?',guardian?'নিচের বিষয়গুলি কতবার দেখেছেন?':'এই বিষয়গুলিতে কতবার অসুবিধা হয়েছে?')}</p><div class="care-scale-labels"><span>0 · ${T('Never','কখনও নয়')}</span><span>1 · ${T('Rarely','খুব কম')}</span><span>2 · ${T('Sometimes','কখনও কখনও')}</span><span>3 · ${T('Often','প্রায়ই')}</span><span>4 · ${T('Very often','খুব প্রায়ই')}</span></div>${factors.map((x,i)=>`<fieldset class="care-factor"><legend><b>${i+1<10?'0':''}${i+1}.</b> ${esc(T(x[0],x[1]))}</legend><p>${esc(T(x[2],x[3]))}</p><div class="care-radio-row" role="group" aria-label="${esc(T(x[0],x[1]))}">${[0,1,2,3,4].map(v=>`<label><input required type="radio" name="factor${i}" value="${v}" ${result?.level===state.level&&result.values[i]===v?'checked':''}/><span>${v}</span></label>`).join('')}</div></fieldset>`).join('')}${adult()?`<label class="care-consent"><input type="checkbox" name="keep"/> <span>${T('Also save this summary in this browser for my future timeline. Other users of this device may see it.','এই ব্রাউজারে ভবিষ্যতের জন্য সারাংশ রাখব। অন্য ব্যবহারকারীরাও দেখতে পারেন।')}</span></label>`:''}<button class="v3-main-button" type="submit">${T('Understand my answers','উত্তরগুলি বুঝুন')} ↗</button></form>`}</section><aside class="care-academic-aside">${result?.level===state.level?careAcademicResult(result,factors):`<div class="care-academic-placeholder"><span>◈</span><h2>${T('Clarity, not a label.','বুঝে নিন, লেবেল নয়।')}</h2><p>${T('After the six responses, you will see the areas you selected most often and an optional practical next step. No diagnosis or comparison across different student stages.','ছয়টি উত্তর দেওয়ার পর সবচেয়ে বেশি চিহ্নিত ক্ষেত্র ও পরের ছোট পদক্ষেপ দেখবেন। এটি কোনো রোগনির্ণয় নয়।')}</p></div>`}<div class="care-aside-help"><strong>${T('If support feels important','সহায়তা দরকার হলে')}</strong><p>${T('Persistent difficulties with learning, sleep or relationships deserve a conversation with a qualified professional.','পড়া, ঘুম বা সম্পর্কে সমস্যা চললে বিশেষজ্ঞের সঙ্গে কথা বলুন।')}</p><a href="#/support" class="care-text-link">${T('Find support','সহায়তা খুঁজুন')} ↗</a></div></aside></div></div>`,true);
}
function careAcademicResult(res,factors){const order=res.values.map((value,i)=>({i,value})).sort((a,b)=>b.value-a.value);const highest=order.filter(x=>x.value===order[0].value&&x.value>0);const top=highest.length?highest.slice(0,3):[];const ex=top.length?T('The most frequent difficulties selected were: ','সবচেয়ে বেশি চিহ্নিত বিষয়: ')+top.map(x=>T(factors[x.i][0],factors[x.i][1])).join(', '):T('No difficulties were selected for these six prompts.','এই ছয়টি ক্ষেত্রে কোনো অসুবিধা চিহ্নিত হয়নি।');
 return `<div class="care-result"><span class="care-overline dark">${T('YOUR REFLECTION SUMMARY','আপনার পর্যবেক্ষণের সারাংশ')}</span><h2>${T('Areas worth noticing','লক্ষ্য করার ক্ষেত্র')}</h2><p>${esc(ex)}</p><div class="care-result-bars">${res.values.map((value,i)=>`<div class="care-result-item"><div><span>${esc(T(factors[i][0],factors[i][1]))}</span><b>${value}/4</b></div><div class="care-track"><i style="width:${value*25}%"></i></div></div>`).join('')}</div><p class="care-small">${T('Values show the frequency selected for each question (0–4), not a clinical score. A guardian observation is not equivalent to a child’s own report.','প্রতিটি উত্তর শুধু ০–৪ মাত্রায় কতবার ঘটেছে বোঝায়; চিকিৎসাগত স্কোর নয়। অভিভাবকের উত্তর শিশুর নিজের উত্তরের সমতুল্য নয়।')}</p><a class="v3-main-button" href="#/plan">${T('Explore a gentle plan','সহজ পরিকল্পনা দেখুন')} ↗</a></div>`;}
function careTimeline(){const events=[];for(const x of state.entries){if(x.kind==='mood')events.push({date:x.time,group:'mood',title:T('Mood diary entry','মুড ডায়েরি'),detail:T(`Energy: ${x.energy}/5`,`শক্তি: ${x.energy}/৫`),value:Number(x.energy)});else if(x.kind==='report')events.push({date:x.time,group:'report',title:T('Saved response summary','সেভ করা উত্তরের সারাংশ'),detail:`${esc(x.type||'')} · ${x.pct}%`,value:null});}for(const x of v3Data.landscape)events.push({date:x.date,group:'weather',title:T('Emotional weather','মনের আকাশ'),detail:x.label||x.id||'',value:null});for(const x of careData.academic)events.push({date:x.date,group:'academic',title:T('Academic pressure reflection','শিক্ষাগত চাপ'),detail:T('Six areas reviewed','ছয়টি ক্ষেত্র পর্যালোচনা'),value:x.values.reduce((a,b)=>a+b,0)/6});events.sort((a,b)=>new Date(b.date)-new Date(a.date));
 const days=Array.from({length:14},(_,i)=>{const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-(13-i));const key=d.toLocaleDateString('en-CA');const es=state.entries.filter(x=>x.kind==='mood'&&new Date(x.time).toLocaleDateString('en-CA')===key);return {label:d.toLocaleDateString(state.lang==='bn'?'bn-IN':'en-IN',{day:'numeric',month:'short'}),n:es.length,val:es.length?es.reduce((s,x)=>s+Number(x.energy||0),0)/es.length:null};});
 return shell(`<div class="care-space">${v3Banner(T('PERSONAL WELLBEING TIMELINE','সময়ের সঙ্গে পরিবর্তন'),T('Notice patterns with kindness.','নরমভাবে পরিবর্তন দেখুন।'),T('A timeline of your own entries on this device or session. A chart is not a prediction or diagnosis.','এই ব্রাউজার বা সেশনের ব্যক্তিগত পর্যবেক্ষণ। চার্ট রোগনির্ণয় বা ভবিষ্যদ্বাণী নয়।'))}<div class="care-timeline-grid"><section class="care-paper"><div class="care-row"><div><span class="care-overline dark">${T('PAST TWO WEEKS','শেষ দুই সপ্তাহ')}</span><h2>${T('Self-reported energy','নিজের দেওয়া শক্তির মাত্রা')}</h2></div><a href="#/diary" class="care-text-link">${T('Add check-in','অনুভূতি লিখুন')} ↗</a></div><div class="care-chart" role="img" aria-label="${T('Energy bar chart of the last 14 days with gaps for days without entries','শেষ ১৪ দিনের শক্তির চার্ট')}">${days.map(d=>`<div class="care-chart-col"><small>${d.val!=null?d.val.toFixed(1):'—'}</small><div class="care-chart-well">${d.val!=null?`<span style="height:${Math.max(6,d.val/5*100)}%"></span>`:''}</div><em>${esc(d.label)}</em></div>`).join('')}</div><p class="care-small">${T('Days with no entries remain blank. Higher energy is not always better; it is only what you selected.','যেদিন লেখা নেই সেদিন খালি। বেশি শক্তি সবসময় ভালো বোঝায় না।')}</p></section><section class="care-paper"><span class="care-overline dark">${T('RECENT REFLECTIONS','সাম্প্রতিক পর্যবেক্ষণ')}</span><h2>${T('Your own activity trail','আপনার নিজস্ব তালিকা')}</h2><div class="care-event-list">${events.length?events.slice(0,20).map(x=>`<article class="care-event"><span class="care-event-dot ${x.group}"></span><div><strong>${esc(x.title)}</strong><p>${esc(x.detail)}</p></div><time>${esc(careSafeDate(x.date))}</time></article>`).join(''):`<div class="care-empty"><span>☾</span><p>${T('Your reflections will appear here when you choose to record them.','লিখলে আপনার পর্যবেক্ষণ এখানে দেখা যাবে।')}</p></div>`}</div></section></div><div class="care-note">${I('shield',19)} <span>${T('Different questionnaires and guardian observations measure different things. Their numerical scores must not be treated as directly comparable. Adults may save entries to this browser; minors’ data stays within the session.','বিভিন্ন প্রশ্ন ও অভিভাবকের পর্যবেক্ষণ এক জিনিস মাপে না। তাদের স্কোর সরাসরি তুলনা করা যায় না। প্রাপ্তবয়স্করা ব্রাউজারে তথ্য রাখতে পারেন; শিশুদের তথ্য সেশনেই থাকে।')}</span></div></div>`,true);
}
function careLiteracy(){const ids=Object.keys(careTopics);return shell(`<div class="care-space">${v3Banner(T('MENTAL HEALTH LITERACY','মানসিক স্বাস্থ্য শিক্ষা'),T('Good information makes space for better choices.','সঠিক তথ্য ভালো সিদ্ধান্তে সহায়ক।'),T('Plain-language topics, short guided reflections, and links to original health resources.','সহজ ভাষায় বিষয়, ছোট অনুশীলন ও আসল স্বাস্থ্যতথ্যের লিঙ্ক।'))}<div class="care-literacy-grid">${ids.map(id=>{const v=careTopics[id];return `<a class="care-literacy-card" href="#/learning/${id}"><span>${v.icon}</span><h2>${T(v.en,v.bn)}</h2><p>${T(v.desc[0],v.desc[1])}</p><b>${T('Read and reflect','পড়ুন ও ভাবুন')} ↗</b></a>`;}).join('')}</div><section class="care-insight-band"><div><span class="care-overline dark">${T('WATCH & REFLECT','দেখুন ও ভাবুন')}</span><h2>${T('Learning can be a conversation.','আলাপের মধ্যেও শেখা যায়।')}</h2><p>${T('Pair selected talks with thoughtful reflection questions. Educational videos and motivational speeches are not substitutes for professional care.','নির্বাচিত ভিডিও দেখে কিছু প্রশ্ন নিয়ে ভাবুন। ভিডিও বা অনুপ্রেরণামূলক বক্তব্য বিশেষজ্ঞের বিকল্প নয়।')}</p><a href="#/guided-media" class="care-text-link">${T('Open guided video learning','ভিডিও শেখার অংশ')} ↗</a></div><span aria-hidden="true" class="care-insight-icon">☼</span></section></div>`,true);}
function careLearning(id){const topic=careTopics[id]||careTopics.stress;return shell(`<div class="care-space"><a class="care-back" href="#/literacy">← ${T('All learning topics','সব বিষয়')}</a>${v3Banner(T('A LITTLE KNOWLEDGE, AT YOUR PACE','নিজের গতিতে শিখুন'),T(topic.en,topic.bn),T(topic.desc[0],topic.desc[1]))}<div class="care-lesson-layout"><section class="care-lesson-hero"><span class="care-lesson-icon">${topic.icon}</span><span class="care-overline">${T('A THREE-STEP REFLECTION','তিনটি ছোট ধাপ')}</span><h2>${T('Learn. Notice. Choose.','শিখুন। দেখুন। বেছে নিন।')}</h2><p>${T('This exercise is for reflection. You do not need to save, share or score your answers.','এটি ভাবনার জন্য। কোনো উত্তর সেভ, শেয়ার বা স্কোর করার দরকার নেই।')}</p><a href="${topic.url}" target="_blank" rel="noopener noreferrer">${T('Read a trusted source','বিশ্বস্ত উৎস পড়ুন')} ↗</a></section><section class="care-paper"><div class="care-lesson-steps">${topic.steps.map((s,i)=>`<div class="care-lesson-step"><span>0${i+1}</span><div><h3>${T(s[0],s[1])}</h3><p>${T(s[2],s[3])}</p></div></div>`).join('')}</div><div class="care-note">${I('heart',18)} <span>${T('If concerns are persistent or severe, a qualified health professional can help you decide what to do next.','সমস্যা দীর্ঘস্থায়ী বা তীব্র হলে স্বাস্থ্য বিশেষজ্ঞ সাহায্য করতে পারেন।')}</span></div><a class="v3-main-button" href="#/plan">${T('Explore a wellbeing plan','সুস্থতার পরিকল্পনা')} ↗</a></section></div></div>`,true);}
function careGuided(){return shell(`<div class="care-space">${v3Banner(T('GUIDED VIDEO LEARNING','ভিডিও দেখে শিখুন'),T('Watch something meaningful. Reflect for a moment.','অর্থপূর্ণ কিছু দেখুন। একটু ভাবুন।'),T('Use the existing curated video library, then reflect on one useful takeaway. Videos open on YouTube by choice only.','নির্বাচিত ভিডিও দেখুন, তারপর একটি কাজে লাগার কথা ভাবুন। ক্লিক করলে ইউটিউব খুলবে।'))}<div class="care-guided-layout"><section class="care-paper"><span class="care-overline dark">${T('CHOOSE A REFLECTION','একটি বিষয় বেছে নিন')}</span><div class="care-topic-pills">${['stress','exams','connection','family'].map(id=>`<button type="button" data-care="topic" data-id="${id}" aria-pressed="${careLearnTopic===id}" class="${careLearnTopic===id?'on':''}">${T(careTopics[id].en,careTopics[id].bn)}</button>`).join('')}</div><div class="care-guided-picture">▶</div><h2>${T(careTopics[careLearnTopic].en,careTopics[careLearnTopic].bn)}</h2><p>${T('Choose a relevant original-creator video from Watch & Learn. Return here to answer one question about what you learned.','ভিডিও লাইব্রেরি থেকে বিষয় অনুযায়ী ভিডিও বেছে দেখুন। ফিরে এসে কী শিখলেন ভাবুন।')}</p><a class="v3-main-button" href="#/videos">${T('Browse curated videos','ভিডিও দেখুন')} ↗</a></section><section class="care-paper"><span class="care-overline dark">${T('REFLECTION PROMPTS','ভাবনার প্রশ্ন')}</span><h2>${T('What will stay with you?','কোন কথাটি মনে রাখবেন?')}</h2><div class="care-prompt">${[T('What idea felt useful, even if you do not agree with every point?','কোন কথাটি কাজে লাগতে পারে, সব কথায় একমত না হলেও?'),T('What would be one realistic, gentle action to try this week?','এই সপ্তাহে কোন একটি ছোট কাজ চেষ্টা করতে পারেন?'),T('Who could you speak with if you wanted additional support?','আরও সাহায্য দরকার হলে কার সঙ্গে কথা বলবেন?')].map((p,i)=>`<button data-care="prompt" data-n="${i}" class="${careLearnStep===i?'selected':''}"><b>0${i+1}</b>${p}</button>`).join('')}</div><div class="care-note">${I('info',18)} <span>${T('No video viewing history or reflection answers are collected by Mind-sage.','কোন ভিডিও দেখেছেন বা কী ভেবেছেন, মাইন্ড-সেজ সংরক্ষণ করে না।')}</span></div><a href="#/support" class="care-text-link">${T('Professional support resources','বিশেষজ্ঞ সহায়তা')} ↗</a></section></div></div>`,true);}
function careResearch(){if(!adult())return shell(`<div class="care-space">${v3Banner(T('RESEARCH EVALUATION','গবেষণা মূল্যায়ন'),T('Participation is separate from personal wellbeing.','গবেষণা ও ব্যক্তিগত যত্ন আলাদা।'),T('This local demonstration of a usability questionnaire is currently for adults only.','এই স্থানীয় ব্যবহারযোগ্যতার প্রশ্নগুলি বর্তমানে শুধু প্রাপ্তবয়স্কদের জন্য।'))}<section class="care-paper care-research-guard">${I('shield',42)}<h2>${T('Adult participation only','শুধু প্রাপ্তবয়স্কদের জন্য')}</h2><p>${T('For any study involving minors, use an institutionally approved protocol with appropriate permission, assent, and safeguarding. No data are being collected by the website.','অপ্রাপ্তবয়স্কদের গবেষণার জন্য নৈতিক অনুমোদন, অভিভাবকের সম্মতি, শিশুর সম্মতি ও সুরক্ষা প্রয়োজন। এই ওয়েবসাইট কোনো তথ্য সংগ্রহ করছে না।')}</p><a href="#/compass" class="v3-main-button">${T('Return to my space','আমার স্থানে ফিরুন')}</a></section></div>`,true);
 const questions=[['I could find the activity I wanted to use.','আমি যে কাজটি করতে চেয়েছি সহজে খুঁজে পেয়েছি।'],['The text was understandable for my educational stage.','আমার শিক্ষাস্তর অনুযায়ী লেখা বোঝা সহজ ছিল।'],['The purpose of each screen was clear to me.','প্রতিটি পৃষ্ঠার উদ্দেশ্য স্পষ্ট ছিল।'],['I could complete the assessment without unnecessary confusion.','অপ্রয়োজনীয় বিভ্রান্তি ছাড়া মূল্যায়ন করতে পেরেছি।'],['I understood how my response summary was calculated.','উত্তরের সারাংশ কীভাবে হিসাব হয়েছে বুঝেছি।'],['The privacy choices were easy to understand.','তথ্যের গোপনীয়তার বিকল্পগুলি বোঝা সহজ ছিল।'],['The wellbeing guidance felt relevant to my needs.','পরামর্শগুলি আমার জন্য প্রাসঙ্গিক মনে হয়েছে।'],['I would feel comfortable returning to this website.','এই ওয়েবসাইটে আবার আসতে স্বাচ্ছন্দ্যবোধ করব।']];
 return shell(`<div class="care-space">${v3Banner(T('VOLUNTARY USABILITY REFLECTION','স্বেচ্ছায় ব্যবহারযোগ্যতার মতামত'),T('Help evaluate the experience—not your health.','ওয়েবসাইটের ব্যবহার নিয়ে মতামত দিন।'),T('A local questionnaire prototype for usability testing. Nothing is automatically submitted to a researcher, university or server.','ব্যবহারযোগ্যতা মূল্যায়নের স্থানীয় প্রশ্ন। কোনো উত্তর স্বয়ংক্রিয়ভাবে গবেষক, বিশ্ববিদ্যালয় বা সার্ভারে যায় না।'))}<section class="care-research-grid"><div class="care-paper"><span class="care-overline dark">${T('STUDY READINESS','গবেষণার প্রস্তুতি')}</span><h2>${T('Before a formal study','আনুষ্ঠানিক গবেষণার আগে')}</h2><p>${T('A real participant study needs an approved research protocol, recruitment criteria, appropriate consent, secure collection, a withdrawal process and planned analyses. This page only lets an adult explore and export their own responses.','প্রকৃত গবেষণার জন্য অনুমোদিত প্রোটোকল, অংশগ্রহণের নিয়ম, সম্মতি, নিরাপদ তথ্য সংগ্রহ ও প্রত্যাহারের ব্যবস্থা দরকার। এখানে প্রাপ্তবয়স্করা নিজের উত্তর ডাউনলোড করতে পারেন।')}</p><div class="care-research-checks">${[T('I explored the navigation and chose a learning stage.','আমি নেভিগেশন ও শিক্ষাস্তর দেখেছি।'),T('I completed or reviewed a wellbeing questionnaire.','আমি মূল্যায়ন পূরণ বা পর্যালোচনা করেছি।'),T('I explored at least one wellbeing activity.','আমি অন্তত একটি যত্নের কাজ দেখেছি।')].map((x,i)=>`<label><input type="checkbox" id="care-task-${i}"/> ${x}</label>`).join('')}</div></div><div class="care-paper"><span class="care-overline dark">${T('EIGHT ORIGINAL USABILITY PROMPTS','আটটি মৌলিক ব্যবহারযোগ্যতার প্রশ্ন')}</span><h2>${T('Your experience with Mind-sage','মাইন্ড-সেজ ব্যবহারের অভিজ্ঞতা')}</h2><form id="care-research-form"><p class="care-small">${T('Rate from 1 = strongly disagree to 5 = strongly agree. This is a newly written feedback checklist, not a standardized validated scale.','১ = একেবারেই একমত নই থেকে ৫ = সম্পূর্ণ একমত। এটি নতুন লেখা মতামতের প্রশ্ন, যাচাইকৃত মানদণ্ড নয়।')}</p>${questions.map(([en,bn],i)=>`<fieldset class="care-research-item"><legend>${i+1}. ${T(en,bn)}</legend><div class="care-radio-row" role="group" aria-label="${esc(T(en,bn))}">${[1,2,3,4,5].map(j=>`<label><input type="radio" required name="r${i}" value="${j}"/><span>${j}</span></label>`).join('')}</div></fieldset>`).join('')}<label class="care-consent"><input required name="consent" type="checkbox"/><span>${T('I am at least 18 and understand that the file I choose to download stays under my control. It is not sent anywhere by this website.','আমার বয়স অন্তত ১৮ এবং বুঝেছি ডাউনলোড করা ফাইল আমার নিয়ন্ত্রণে থাকবে। এই ওয়েবসাইট কোথাও পাঠাবে না।')}</span></label><button class="v3-main-button" type="submit">${T('Download my feedback CSV','আমার মতামত CSV নামান')} ↗</button><div class="care-form-msg" id="care-research-status" role="status"></div></form></div></section></div>`,true);
}
function careVault(){return shell(`<div class="care-space">${v3Banner(T('YOUR DATA & PRIVACY','আপনার তথ্য ও গোপনীয়তা'),T('You decide what stays.','কোন তথ্য থাকবে, আপনি ঠিক করুন।'),T('Review saved information, create an encrypted personal backup if eligible, or clear local data.','সেভ করা তথ্য দেখুন, চাইলে এনক্রিপ্টেড ব্যাকআপ রাখুন বা তথ্য মুছুন।'))}<div class="care-vault-grid"><section class="care-paper"><span class="care-overline dark">${T('LOCAL INFORMATION','ডিভাইসের তথ্য')}</span><h2>${T('What is saved here?','এখানে কী আছে?')}</h2><div class="care-vault-list"><div><span>${T('Mood / saved response summaries','মুড ও উত্তরের সারাংশ')}</span><strong>${state.entries.length}</strong></div><div><span>${T('Journal notes','জার্নালের লেখা')}</span><strong>${v3Data.journal.length}</strong></div><div><span>${T('Academic reflections','শিক্ষাগত পর্যবেক্ষণ')}</span><strong>${careData.academic.length}</strong></div><div><span>${T('Garden and landscape moments','বাগান ও অনুভূতির আকাশ')}</span><strong>${v3Data.garden.length+v3Data.landscape.length}</strong></div></div><p class="care-small">${T('The website does not upload these records. On shared devices, locally saved data may be readable by another person using the same browser. Under-18 personal entries remain session-only.','ওয়েবসাইট এই তথ্য সার্ভারে পাঠায় না। একই ব্রাউজারের অন্য ব্যবহারকারীরা সেভ করা তথ্য দেখতে পারেন। শিশুদের তথ্য সেশনেই থাকে।')}</p><button class="care-danger-button" data-care="clear-data">${I('trash',18)} ${T('Clear personal data from this browser','এই ব্রাউজারের ব্যক্তিগত তথ্য মুছুন')}</button><a class="care-text-link" href="#/privacy">${T('Complete privacy details','বিস্তারিত গোপনীয়তা')} ↗</a></section><section class="care-paper"><span class="care-overline dark">${T('OPTIONAL ENCRYPTED BACKUP','ঐচ্ছিক এনক্রিপ্টেড ব্যাকআপ')}</span><h2>${T('Protect an exported copy.','এক্সপোর্ট করা তথ্য সুরক্ষিত রাখুন।')}</h2>${adult()?`<p>${T('A passphrase encrypts the backup file in your browser using AES-GCM. It is never sent to a server. Keep the passphrase yourself; lost passphrases cannot be recovered.','ব্রাউজারে AES-GCM দিয়ে ব্যাকআপ এনক্রিপ্ট হবে। পাসফ্রেজ সার্ভারে যাবে না। পাসফ্রেজ হারালে ফাইল খুলতে পারবেন না।')}</p><form id="care-backup-form"><label class="care-field">${T('Backup passphrase (at least 12 characters)','ব্যাকআপ পাসফ্রেজ (অন্তত ১২ অক্ষর)')}<input type="password" name="passphrase" minlength="12" autocomplete="new-password" required /></label><label class="care-consent"><input type="checkbox" name="understand" required/> ${T('I understand that this export may contain private journal and assessment summaries.','আমি বুঝেছি এই ফাইলে ব্যক্তিগত লেখা ও সারাংশ থাকবে।')}</label><button class="v3-main-button" type="submit">${I('download',17)} ${T('Download encrypted backup','এনক্রিপ্টেড ব্যাকআপ নামান')}</button></form><div class="care-import"><label class="care-field">${T('Restore a previous Mind-sage backup','আগের মাইন্ড-সেজ ব্যাকআপ ফিরিয়ে আনুন')}<input type="file" id="care-backup-file" accept=".json,application/json" /></label><label class="care-field">${T('Backup passphrase','ব্যাকআপ পাসফ্রেজ')}<input type="password" id="care-restore-password" autocomplete="off" /></label><button type="button" class="care-quiet-button" data-care="restore">${T('Restore after confirmation','নিশ্চিত করে ফিরিয়ে আনুন')}</button></div>`:`<div class="care-note">${I('shield',20)} ${T('Encrypted backups are offered only for adult profiles. For younger students, personal content is not persisted across visits.','এনক্রিপ্টেড ব্যাকআপ শুধু প্রাপ্তবয়স্কদের জন্য। শিশুদের তথ্য দীর্ঘদিন সেভ করা হয় না।')}</div>`}<div class="care-form-msg" id="care-vault-msg" role="status"></div></section></div></div>`,true);
}
function carePage(path){switch(path[0]){case 'compass':return careCompass();case 'guardian':return careGuardian();case 'academic':return careAcademic();case 'timeline':return careTimeline();case 'literacy':return careLiteracy();case 'learning':return careLearning(path[1]);case 'guided-media':return careGuided();case 'evaluation':return careResearch();case 'vault':return careVault();default:return null;}}
function careDownload(name,content,type='text/plain'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function careB64(b){const a=new Uint8Array(b);let s='';for(let i=0;i<a.length;i+=8192)s+=String.fromCharCode(...a.subarray(i,i+8192));return btoa(s);}
function careUnB64(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0));}
async function careCryptoKey(pass,salt){const base=await crypto.subtle.importKey('raw',new TextEncoder().encode(pass),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:210000,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);}
function careMsg(txt){let m=document.getElementById('care-vault-msg');if(m)m.textContent=txt;}
async function careBackup(e){e.preventDefault();if(!adult())return;const f=e.target,pass=f.elements.passphrase.value;if(pass.length<12)return;const obj={format:'mind-sage-local-backup',data:{entries:state.entries,v3:v3Data,care:{academic:careData.academic.filter(x=>x.keep)}}};try{const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await careCryptoKey(pass,salt),out=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(JSON.stringify(obj)));careDownload('mind-sage-private-backup-'+dateStamp()+'.json',JSON.stringify({format:'mind-sage-encrypted-backup',salt:careB64(salt),iv:careB64(iv),payload:careB64(out)},null,2),'application/json');f.reset();careMsg(T('Encrypted backup downloaded. Keep the password separately.','এনক্রিপ্টেড ব্যাকআপ নামানো হয়েছে। পাসফ্রেজ আলাদা করে রাখুন।'));}catch(err){console.error(err);careMsg(T('Your browser could not create the encrypted backup.','ব্রাউজারে এনক্রিপ্টেড ব্যাকআপ তৈরি করা গেল না।'));}}
async function careRestore(){if(!adult())return;const input=document.querySelector('#care-backup-file'),pass=document.querySelector('#care-restore-password')?.value||'';const file=input?.files?.[0];if(!file||!pass){careMsg(T('Choose a backup file and enter its passphrase.','ব্যাকআপ ফাইল ও পাসফ্রেজ দিন।'));return;}if(file.size>8000000){careMsg(T('Backup is too large.','ব্যাকআপ ফাইল খুব বড়।'));return;}try{const wrapper=JSON.parse(await file.text());if(wrapper.format!=='mind-sage-encrypted-backup')throw Error('Invalid format');const key=await careCryptoKey(pass,careUnB64(wrapper.salt));const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:careUnB64(wrapper.iv)},key,careUnB64(wrapper.payload));const obj=JSON.parse(new TextDecoder().decode(plain));if(obj.format!=='mind-sage-local-backup'||!obj.data||!Array.isArray(obj.data.entries)||!Array.isArray(obj.data.v3?.journal)||!Array.isArray(obj.data.care?.academic))throw Error('Invalid content');if(!confirm(T('This will replace locally saved Mind-sage records in this browser. Continue?','এতে এই ব্রাউজারে সেভ করা তথ্য বদলে যাবে। এগোবেন?')))return;
const d=obj.data;state.entries=d.entries.filter(x=>x&&typeof x==='object'&&['mood','report'].includes(x.kind)).slice(-120);v3Data={...V3_DATA_DEFAULT(),...d.v3};careData={...careNew(),academic:d.care.academic.filter(x=>x&&x.keep&&Array.isArray(x.values)).slice(-80)};localStorage.setItem(NS,JSON.stringify(state.entries));localStorage.setItem(V3_STORE_KEY,JSON.stringify(v3Data));careSave();document.querySelector('#care-restore-password').value='';alert(T('Your backup was restored in this browser.','ব্যাকআপ এই ব্রাউজারে ফিরিয়ে আনা হয়েছে।'));render();}catch(err){careMsg(T('Unable to restore. Check the file and passphrase.','ব্যাকআপ খোলা গেল না। ফাইল ও পাসফ্রেজ যাচাই করুন।'));}}
function careErase(){if(!confirm(T('Delete all personal wellbeing entries, journals, plans and reflections saved by Mind-sage in this browser? This cannot be undone.','এই ব্রাউজারে মাইন্ড-সেজের সব ব্যক্তিগত লেখা, পরিকল্পনা ও পর্যবেক্ষণ মুছবেন? ফেরানো যাবে না।')))return;state.entries=[];v3Data=V3_DATA_DEFAULT();careData=careNew();careResults=null;for(const k of [NS,V3_STORE_KEY,careStoreKey])localStorage.removeItem(k);render();}
function careClick(e){const btn=e.target.closest('[data-care]');if(!btn)return;e.preventDefault();e.stopImmediatePropagation();switch(btn.dataset.care){case 'topic':careLearnTopic=btn.dataset.id;render();break;case 'prompt':careLearnStep=Number(btn.dataset.n);render();break;case 'clear-data':careErase();break;case 'restore':careRestore();break;case 'plan-feedback':if(v3Data.plan){v3Data.plan.feedback={rating:btn.dataset.rating,date:new Date().toISOString()};v3Save();render();}break;}}
function careSubmit(e){const f=e.target;if(!['care-academic-form','care-research-form','care-backup-form'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();if(f.id==='care-backup-form'){careBackup(e);return;}
 if(f.id==='care-academic-form'){if(!state.profileReady)return;const data=new FormData(f),values=Array.from({length:6},(_,i)=>Number(data.get('factor'+i)));if(values.some(x=>!Number.isInteger(x)||x<0||x>4))return;const summary={level:state.level,date:new Date().toISOString(),values,keep:!!(adult()&&data.get('keep'))};careResults=summary;careData.academic.push(summary);careData.academic=careData.academic.slice(-80);if(summary.keep)careSave();render();return;}
 if(f.id==='care-research-form'){if(!adult()||!f.elements.consent.checked)return;const data=new FormData(f),scores=Array.from({length:8},(_,i)=>Number(data.get('r'+i)));if(scores.some(x=>!Number.isInteger(x)||x<1||x>5))return;const tasks=[0,1,2].map(i=>document.querySelector('#care-task-'+i)?.checked?'Yes':'No');const rows=[['study_instrument','stage','feedback_mean','task_navigation','task_assessment','task_activity',...scores.map((_,i)=>'question_'+(i+1))],['Mind-sage-original-usability-questions',state.level||'not_selected',(scores.reduce((a,b)=>a+b,0)/8).toFixed(2),...tasks,...scores.map(String)]];careDownload('mind-sage-usability-feedback.csv','\ufeff'+rows.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8');const s=document.getElementById('care-research-status');if(s)s.textContent=T('Your CSV is downloaded. Nothing was submitted online.','CSV ডাউনলোড হয়েছে। অনলাইনে কিছু পাঠানো হয়নি।');}}
// Extend existing navigation: no change to the assessment bank, Vani collection or video selection.
const careLinks=[['compass','target','Mind Compass','মনের দিশা'],['academic','chart','Academic pressure','শিক্ষাগত চাপ'],['guardian','users','Guardian Care Hub','অভিভাবকের যত্ন'],['timeline','calendar','Wellbeing Timeline','সময়ের সঙ্গে পরিবর্তন'],['literacy','book','Literacy Centre','জানার কেন্দ্র'],['guided-media','play','Guided video learning','ভিডিও থেকে শেখা'],['vault','shield','My data & privacy','আমার তথ্য ও গোপনীয়তা'],['evaluation','chart','Usability evaluation','ব্যবহারযোগ্যতার মতামত']];
for(const item of [...careLinks].reverse())if(!navs.some(n=>n[0]===item[0]))navs.unshift(item);
const careLandingBase=v3Landing;v3Landing=function(){return careLandingBase().replace('</main>',`<section class="care-home-promo"><span>✧</span><div><small>${T('YOUR PERSONAL SPACE','আপনার ব্যক্তিগত স্থান')}</small><h2>${T('Find your direction with Mind Compass.','মনের দিশা খুঁজুন মাইন্ড কম্পাসে।')}</h2><p>${T('A new way to explore your stage, academic pressures and meaningful next steps.','নিজের শিক্ষাস্তর, পড়াশোনার চাপ ও ছোট পদক্ষেপ দেখুন।')}</p></div><a href="#/compass">${T('Open Mind Compass','মাইন্ড কম্পাস খুলুন')} ↗</a></section></main>`);};
const careAdviceBase=v3Advice;
v3Advice=function(){
 const original=careAdviceBase(),recent=[...careData.academic].reverse().find(x=>x.level===state.level)||careResults;
 if(!recent||recent.level!==state.level)return original;
 const factors=careFactors[state.level]||careFactors.ug;
 const best=recent.values.map((value,i)=>({value,i})).sort((a,b)=>b.value-a.value)[0];
 if(!best||best.value<2)return original;
 const category=String(factors[best.i]?.[0]||'');
 let focus=/sleep|rest|work-life|time management/i.test(category)?'rest':/social|peer|supervis|isolation|home|family|support/i.test(category)?'connection':/physical|separation/i.test(category)?'worry':'study';
 const because=T(`You selected “${category}” relatively often during your academic reflection. A gentle ${v3FocusLabel(focus).toLowerCase()} activity may be worth trying.`,`আপনার শিক্ষাগত পর্যবেক্ষণে “${factors[best.i][1]}” তুলনামূলক বেশি চিহ্নিত হয়েছে। ${v3FocusLabel(focus)}-এর একটি সহজ কাজ চেষ্টা করতে পারেন।`);
 return {focus,because,why:T('A visible if-then suggestion based on the most frequently selected academic factor. You are free to choose another plan. This is not a clinical prediction.','সবচেয়ে বেশি চিহ্নিত বিষয়ের ভিত্তিতে সহজ নিয়মভিত্তিক পরামর্শ। চাইলে অন্য পরিকল্পনা বেছে নিন। এটি চিকিৎসাগত পূর্বাভাস নয়।')};
};
const carePlanBase=v3Plan;
v3Plan=function(){let html=carePlanBase();if(typeof html!=='string'||!v3Data.plan)return html;const feedback=v3Data.plan.feedback?.rating||null;const prompt=`<section class="care-plan-reflect"><div><span class="care-overline dark">${T('REVIEW YOUR OWN EXPERIENCE','নিজের অভিজ্ঞতা পর্যালোচনা')}</span><h2>${T('How helpful did the activities feel?','কাজগুলি কতটা সাহায্য করেছে?')}</h2><p>${T('Optional reflection only. You may change your answer. Your feedback does not calculate a mental health score.','ইচ্ছাধীন ভাবনা। উত্তর বদলাতে পারেন। এটি মানসিক স্বাস্থ্য স্কোর তৈরি করে না।')}</p></div><div class="care-feedback-buttons">${[['notyet','Not yet','এখনও নয়'],['little','A little','একটু'],['helpful','Quite helpful','বেশ সহায়ক']].map(([id,en,bn])=>`<button type="button" data-care="plan-feedback" data-rating="${id}" aria-pressed="${feedback===id}" class="${feedback===id?'selected':''}">${T(en,bn)}</button>`).join('')}</div></section>`;return html.replace('</main>',prompt+'</main>');};
const careDashboardBase=v3Dashboard;v3Dashboard=function(){return careDashboardBase().replace('</main>',`<section class="care-dashboard-promo"><div><span class="care-overline dark">${T('ANOTHER WAY TO REFLECT','ভাবার আরেকটি পথ')}</span><h2>${T('Your personal Mind Compass','আপনার মাইন্ড কম্পাস')}</h2><p>${T('See your own check-ins and discover a thoughtful next step.','নিজের অনুভূতি দেখে পরের ছোট পদক্ষেপ খুঁজুন।')}</p></div><a href="#/compass" class="v3-main-button">${T('Explore Compass','কম্পাস দেখুন')} ↗</a></section></main>`);};
const careNavBase=v3AfterNavigate;v3AfterNavigate=function(page){careNavBase(page);if(adult()&&!careLoaded){careLoad();if(['compass','timeline','vault'].includes(page))render();}const brand=document.querySelector('.brand small');if(brand)brand.textContent='YOUR WELLBEING SPACE';document.title='Mind-sage | '+((navs.find(n=>n[0]===page)||[])[2]||'Student wellbeing');const nodes=document.querySelectorAll('.v3-hero-label,.v4-video-kicker,.v3-pagehead .v3-kicker');for(const n of nodes){if(n.textContent?.includes('VERSION'))n.textContent=n.textContent.replace(/\s*·\s*VERSION\s*\d+/ig,'');if(n.textContent?.includes('সংস্করণ'))n.textContent=n.textContent.replace(/\s*·\s*সংস্করণ\s*[০-৯\d]+/g,'');if(n.textContent?.includes('NEW IN V4'))n.textContent=n.textContent.replace('NEW IN V4','FEATURED');if(n.textContent?.includes('V4-এ নতুন'))n.textContent=n.textContent.replace('V4-এ নতুন','নির্বাচিত');}};
document.addEventListener('click',careClick,true);document.addEventListener('submit',careSubmit,true);
// Empty stage and guardian workflow stay available; personal records are reset in memory when selecting a new stage.
document.addEventListener('click',e=>{if(e.target.closest('[data-action="level"]')){careData=careNew();careLoaded=false;careResults=null;}},false);
